template <typename RAIt1, typename RAIt2>
RAIt1 find_end_impl(RAIt1 f1, RAIt1 l1, RAIt2 f2, RAIt2 l2) {
    long N1 = l1 - f1, N2 = l2 - f2;
    if (N2 == 0) return l1;

    // Search potential start positions backward in R1
    for (long i = N1 - N2; i >= 0; --i) {
        bool match = true;

        // Inner comparison loop (std::equal analog)
        for (long j = 0; j < N2; ++j) {
            if (*(f1 + i + j) != *(f2 + j)) {
                match = false;
                break;
            }
        }

        if (match) {
            return f1 + i; // Return the first position of the match
        }
    }
    return l1;
}
